quests[8446] = { id = 8446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingehüllt in Alpträume", description = "Dunkelheit umgibt dieses Objekt.\n\nVielleicht gibt es eine Verbindung zwischen diesem Gegenstand und den aus dem Traum vordringenden Drachen. Sucht nach jemandem, der die Bedeutung dieses Gegenstands entschlüsseln kann. Vielleicht können Euch die Druiden der Mondlichtung oder ihre Vertreter auf Burg Cenarius weiterhelfen.", sourceObjective = "Sucht nach jemandem, der die Bedeutung des in Alpträume gehüllten Gegenstands entschlüsseln kann.\n\nVielleicht kann Euch ein Druide von großer Macht weiterhelfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8447] = { id = 8447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legenden erwachen", description = "Das Wasser des Sees von Elune'ara wird die Alpträume auflösen, die den Gegenstand umgeben. Bitte, gebt mir einen Moment, um die Reinigung durchzuführen, {name}.", sourceObjective = "Wartet, bis Bewahrer Remulos bei der Mondlichtung den von Alpträumen eingehüllten Gegenstand gereinigt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[8460] = { id = 8460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Holzschlundfeste", description = "Die Furbolgs der Holzschlundfeste sind die einzigen Furbolgs, die von der Verderbnis verschont blieben. Aber viele andere Völker töten die Furbolgs jetzt blindwütig und scheren sich nicht darum, ob sie Freund oder Feind sind. Deswegen trauen die Einwohner der Holzschlundfeste auch kaum jemandem.\n\nSeid Ihr daran interessiert, Euch zu beweisen? Treibt den verderbten Stamm der Totenwaldfelle zurück, dann betrachten wir Euch eines Tages vielleicht als Verbündeten. Ihr findet die Krieger, Pfadfinder und Gärtner der Totenwaldfelle im Süden.", sourceObjective = "Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8461] = { id = 8461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totenwaldfelle des Nordens", description = "Direkt südwestlich von hier liegt ein Furbolglager der Totenwaldfelle. Ich bin nicht sicher, was sie vorhaben, aber ich würde dem gern einen Riegel vorschieben, ehe es zum Problem wird.\n\nDer Stamm der Totenwaldfelle ist böse, aber die Verderbnis ist es, die ihre Hirne verseucht. Ihre Feindseligkeit ist keine angeborene Eigenschaft, doch da kann man nichts machen. Aus diesem Grund stimmt es mich zutiefst traurig, dass ich gegen meine Geschwister kämpfen muss.\n\nBitte, {name}, tut, was getan werden muss, aber erspart mir die Einzelheiten. Sie beunruhigen mich zu sehr.", sourceObjective = "Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8462] = { id = 8462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Nafien", description = "Vielleicht seid Ihr stark genug, um Euch einer noch größeren Bedrohung entgegenzustellen. Die Furbolgs der Holzschlundfeste brauchen Eure Hilfe und ich denke, Ihr habt hier bereits Eure Tauglichkeit im Kampf ausreichend bewiesen.\n\nReist auf dieser Straße in Richtung Norden, bis zum Eingang der Holzschlundfeste, wo einer meiner Brüder Wache steht. Sein Name ist Nafien. Im ersten Augenblick mag er vielleicht wie ein ungezügeltes, wildes Tier wirken, doch braucht Ihr ihn nicht zu fürchten. Er ist auf der Suche nach tapferen Abenteurern, die ihm im Kampf gegen die dunkle Verderbnis unterstützen, welche unsere Heimat bedroht.", sourceObjective = "Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg namens Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache.", sourceObjectiveStatus = "unverified-source-field" }
quests[8463] = { id = 8463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instabile Manakristalle", description = "Eine Gruppe Getriebener hat kürzlich einen Vorrat instabiler Manakristalle aus einem unserer arkanen Sankten gestohlen. Wenn man mit den Kristallen nicht umzugehen vermag, können sie mit einer Kraft explodieren, die ausreicht, um ein Loch in die Stadtmauern zu reißen. Nun, {name}, mir kann es egal sein, ob sich diese Narren beim Einverleiben instabiler arkaner Quellen selbst in die Luft sprengen, doch ein solcher Vorfall würde meine Männer schlecht dastehen lassen.\n\nBringt mir alle verbliebenen Kristalle, die Ihr finden könnt; wahrscheinlich lagern sie immer noch in ihren ursprünglichen Kisten.", sourceObjective = "Bringt Aeldon Sonnenmal 6 instabile Manakristalle.", progress = "Habt Ihr die gestohlenen Kristalle gefunden?", completion = "Hervorragende Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8464] = { id = 8464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktivität der Winterfelle", description = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, {name}. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber, wenn möglich, andere Furbolgstämme.\n\nIn letzter Zeit ist mir aufgefallen, dass der Winterfellstamm uns gegenüber immer größere Feindseligkeit zeigt. Sie scheinen in Rage zu sein, und ganz von ihrem Hass auf alles beseelt, das sie nicht verstehen.\n\nEs stimmt mich zwar zutiefst traurig, dass ich gegen meine Geschwister kämpfen muss, trotzdem möchte ich Euch bitten, dass Ihr einige von ihnen ausmerzt, um die Bedrohung, die von ihnen ausgeht, zu verringern. Ihr findet sie im Lager der Winterfelle.", sourceObjective = "Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich genau außerhalb des Eingangs zur Holzschlundfeste in Winterquell.", sourceObjectiveStatus = "unverified-source-field" }
quests[8465] = { id = 8465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Salfa", description = "Die Verderbnis bedroht uns nicht nur in Form der Totenwaldfelle vom Süden her, sondern auch durch die Winterfellfurbolgs im Osten. Wenn Ihr uns auch weiterhin helfen wollt, sprecht mit Salfa auf der anderen Seite der Festung. Ihr findet sie nahe des Eingangs zu Winterquell. Folgt einfach dem linken Pfad, um zu ihr zu gelangen.\n\nDoch seid gewarnt! Sollten meinesgleichen Euch gegenüber hasserfüllt oder gar feindlich eingestellt sein, werden sie Euch angreifen. Sollte dies der Fall sein, durchquert das Gebiet schnellstmöglich und vermeidet alle Kämpfe mit ihnen. Einen Furbolg der Holzschlundfeste zu töten und sei es nur zur Selbstverteidigung, wird Euren Ruf in der Holzschlundfeste nur weiter verschlechtern.", sourceObjective = "Durchquert die Holzschlundfeste und verlasst sie in Richtung Winterquell. Sprecht mit Salfa, die außerhalb des Eingangs zur Holzschlundfeste Wache steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8466] = { id = 8466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn für Grazle" }
quests[8467] = { id = 8467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn für Nafien" }
quests[8468] = { id = 8468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Thaelis der Manadurstige", description = "Hiermit setzt die Stadt Silbermond eine Belohnung auf den Kopf von Thaelis dem Manadurstigen aus, einem notorischen Aufwiegler und Rädelsführer getriebener Blutelfen. Ihm werden verschiedene Verbrechen gegen die Einwohner von Silbermond zur Last gelegt, einschließlich der Ermordung zweier Stadtwachen.\n\nMeldet Euch bei Unteroffizier Kan'ren, um die Belohnung zu erhalten.", sourceObjective = "Bringt Thaelis Kopf zu Unteroffizier Kan'ren beim Falkenplatz im Immersangwald.", progress = "Ihr habt etwas, das Ihr mir zeigen wollt?", completion = "Diesen Halunken, Thaelis, hat endlich sein gerechtes Schicksal ereilt. Gute Arbeit, {name}. Damit sollten wir einige Zeit lang Ruhe vor den Getriebenen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8469] = { id = 8469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perlen für Salfa" }
quests[8470] = { id = 8470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualtotem der Totenwaldfelle", description = "Ihr habt ein Ritualtotem der Totenwaldfelle gefunden. Das Totem selbst ist von unbestimmbarer Machart, aber es geht eine spürbare Verzweiflung davon aus. Gäbe es auch nur eine einzige Sache, die die Verderbnis der Totenwaldfelle veranschaulichen könnte, so wäre es mit Sicherheit dieses Totem.\n\nEiner der Furbolgs innerhalb der Holzschlundfeste könnte vielleicht eine Verwendung für diesen Gegenstand haben... gesetztenfalls Ihr habt Euch genug Vertrauen verdient, um mit ihnen zu sprechen.", sourceObjective = "Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist.", progress = "Ja {class}, wie kann ich Euch helfen? Ihr geht zwar friedlich umher, dennoch scheint etwas nicht zu stimmen. Ich spüre etwas... etwas Beunruhigendes...", completion = "Dieses Totem... ich erkenne es als eines der Totenwaldfelle wieder, allerdings ist es umhüllt vom Gestank der Verderbnis. Was auch immer unsere Brüder gegen uns gerichtet haben mag, es befindet sich in diesem Gegenstand.\n\nEs war weise von Euch, es zu uns zu bringen, {name}. Vielleicht können wir mittels Studien und Ritualen herausfinden, was es ist, das den Geist unserer Brüder so verpestet. Vielen Dank, mein Freund - bitte nehmt diese Gabe im Tausch gegen Euren Fund.", sourceObjectiveStatus = "unverified-source-field" }
quests[8471] = { id = 8471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualtotem der Winterfelle", description = "Ihr habt ein Ritualtotem der Winterfellfurbolgs gefunden. Das Totem selbst ist von unbestimmbarer Machart, aber es geht eine beinahe greifbare Aura der Furcht und Verzweiflung von ihm aus. Sollten tatsächlich alle Furbolgs der Winterfelle ein solches Totem bei sich tragen, würde dies ihren momentanen Zustand sicherlich erklären.\n\nEiner der Furbolgs innerhalb der Holzschlundfeste könnte vielleicht eine Verwendung für diesen Gegenstand haben... gesetztenfalls Ihr habt Euch genug Vertrauen verdient, um mit ihnen zu sprechen.", sourceObjective = "Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8472] = { id = 8472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Fehlfunktion", description = "Die Arkanpatrouillen, einst von unseren Vorvätern zum Schutze dieser Stadt erschaffen, befinden sich in einem gefährlichen Zustand des Verfalls. Sie erkennen uns nicht länger als ihre Herren und greifen uns ohne Vorwarnung an!\n\nObwohl sie schon vor Jahrzehnten konstruiert wurden, sind die Arkankerne, die sie antreiben, für uns immer noch von großem Wert. Ich möchte, dass Ihr einige dieser Kerne sammelt und sie mir bringt, damit wir sie anderweitig sinnvoll einsetzen können. Ihr findet die Patrouillen im zerstörten Teil von Silbermond, im Nordwesten.", sourceObjective = "Sammelt 6 Arkankerne von den Arkanpatrouillen, die in den Ruinen von Silbermond umherstreifen, und bringt sie Magister Jaronis beim Falkenplatz im Immersangwald.", progress = "War Eure Suche nach Arkankernen erfolgreich, {name}?", completion = "Ihr habt Euch gut geschlagen, {name}. Solange die arkanen Sankten nicht vollständig einsatzbereit sind, werden sich diese Kraftkerne als sehr nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8473] = { id = 8473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine traurige Aufgabe", description = "Das sind schwierige Zeiten, {name}. Es war eine schwere Entscheidung, die Wälder am Rande der Geisterlande niederzubrennen, um die weitere Expansion der Geißel zu stoppen.\n\nDie Treants, seit Jahrzehnten unsere Verbündeten, versuchen den niedergebrannten Wald am Versengten Hain wieder aufzuforsten.\n\nEs tut mir in der Seele weh, Euch um diesen Gefallen zu bitten, {class}, doch wir konnten unsere Verbündeten nicht davon abhalten, den Wald zu erneuern. Ihr müsst sie und ihr Vorhaben mit dem einzig noch verbleibenden Mittel beenden: Gewalt.", sourceObjective = "Tötet 10 siechende Waldbehüter beim Versengten Hain und meldet Euch anschließend bei Larianna Flusswind, die sich im Turm nordwestlich des Versengten Hains im Immersangwald aufhält.", completion = "Es ist also getan. Ich verfluche diese Zeit, die uns zu solch verzweifelten Maßnahmen treibt... und ich verfluche unseren Feind, die Geißel!\n\nVerinnerlicht diese Lektion, {name}. Unser Land muss beschützt werden, ganz egal wie hoch der Preis dafür sein mag. Wir werden obsiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8474] = { id = 8474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weißborkes Anhänger", description = "Auf dem Anhänger sind die eingravierten Initialen L.F. lesbar. Vielleicht weisen diese Anfangsbuchstaben ja auf die Person hin, die den Anhänger angefertigt hat.", sourceObjective = "Macht die Person ausfindig, die Weißborkes Anhänger angefertigt haben könnte. Ihr könntet Hinweise über den Gegenstand erfahren.", progress = "Wollt Ihr mir etwas zeigen?", completion = "Dieser... dieser Anhänger. Ich gab ihn Weißborke dem Alten, nachdem seine Leute uns beim Wiederaufbau unseres Dorfes geholfen hatten.\n\nIch vermute, das bedeutet, dass er...\n\n<Die Blutelfe räuspert sich und gewinnt ihre Fassung wieder.>\n\nIch weiß zu schätzen, dass Ihr mir den Anhänger gebracht habt, {name}. Ich muss Euch um einen Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8475] = { id = 8475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todesschneise", description = "Die schwarze Schneise aus verbrannter Erde, welche sich durch den Immersangwald zieht, ist eine ständige Erinnerung an den dunklen Tag, als Arthas die Geißel in unsere geliebte Stadt führte.\n\nDieser Schandfleck ist mehr als nur ein Makel! Selbst heute noch dringen über diesen dunklen Pfad Kreaturen aus den Geisterlanden bis nach Silbermond vor.\n\nGeht, {name}, und reicht meinen Männern Eure helfende Hand, indem Ihr die geistlosen Untoten tötet, welche in der Todesschneise umherstreifen.", sourceObjective = "Tötet 8 Seuchenknochenplünderer und kehrt anschließend zu Waldläuferin Jaela in der Todesschneise im Immersangwald zurück.", completion = "Wir denken nicht, dass die Geißel in absehbarer Zeit ihre Angriffe einstellen wird, dennoch sind wir jedem dankbar, der uns bei der Verteidigung der Schneise unterstützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8476] = { id = 8476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amaniübergriff", description = "Wir herrschen nicht über solch riesige Königreiche wie die Menschen oder die Orcs. Beinahe alles, was uns noch von unseren Ländereien in Azeroth geblieben ist, seht Ihr hier vor Euch, {name}.\n\nBis wir die Scherbenwelt erreichen können, um ein neues Zuhause zu finden, müssen wir das Wenige, das uns geblieben ist, um jeden Preis verteidigen.\n\nUnsere unzivilisierten Nachbarn im Südosten, die Amanitrolle, haben allerdings eine gänzlich andere Auffassung darüber, wem dieses Land gehört. Ihre täglichen Angriffe werden wir nicht länger tolerieren. Begebt Euch zu ihren Siedlungen, Zeb'Watha und Tor'Watha, und erteilt ihnen eine Lektion.", sourceObjective = "Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer im Immersangwald möchte, dass Ihr 5 Berserker der Amani und 5 Axtwerfer der Amani tötet.", completion = "Gute Arbeit, {name}. Mit mehr Leuten wie Euch, wird unser Königreich schon bald zu alter Größe zurückfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8477] = { id = 8477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer des Speermachers", description = "Die Amani und die Sin'dorei pflegen seit langem eine gegenseitige Ablehnung und offenkundige Feindseligkeit. Das hält mich jedoch nicht von der Bewunderung der Arbeit eines Handwerkskollegen ab, {name}.\n\nIch bin auf Stücke von Amaniwaffen gestoßen und muss zugeben, dass ich von der Qualität ihrer Arbeit beeindruckt bin. Man munkelt, dass Speermacher Otembe mit einem magischen Hammer arbeitet, der so leicht und gut ausbalanciert ist, dass er mit großem Geschick und höchst effizient ans Werk gehen kann.\n\nWenn Ihr mir dieses Werkzeug bringt, werde ich Euch damit eine Waffe anfertigen.", sourceObjective = "Sucht in Tor'Watha, südöstlich der Zuflucht der Weltenwanderer, nach Speermacher Otembe und bringt Otembes Hammer zu Arathel Sonnenschmied bei der Zuflucht der Weltenwanderer im Immersangwald.", progress = "Habt Ihr mir Otembes Hammer gebracht, {name}?", completion = "Die Gerüchte entsprechen der Wahrheit, {name}. Dieser Hammer ist leicht und mächtig zugleich; ich werde einige meiner begonnenen Werke fertigstellen können. Natürlich dürft Ihr Euch als Erster etwas von den Gegenständen aussuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8478] = { id = 8478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Eure Waffe" }
quests[8479] = { id = 8479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Marosh", description = "Kommt näher, Mann. Keine Angst, Ven'jashi wird Euch nicht wehtun.\n\nWir Dunkelspeere sind, genau wie Ihr, Erzfeinde der Amani. Ihr Anführer Zul'Marosh ist 'n bösartiger Troll. Er gab mir Gift und ließ mich zum Sterben in diesem Käfig zurück.\n\nIch hab' keine Angst vorm Sterben, Mann. Ich sehe dem Tod ins Auge und lache über ihn.\n\nDoch noch kann ich nicht in Frieden sterben, Mann. Nich' bevor Zul'Marosh tot ist. Sucht ihn jenseits des Sees in Zeb'Watha. Ich werd' das Gift ertragen, bis Ihr mir seinen dicken Kopf gebracht habt, Mann. Erst dann kann ich friedlich sterben.", sourceObjective = "Ven'jashi, der gefangene Troll in Tor'Watha möchte, dass Ihr ihm Häuptling Zul'Maroshs Kopf bringt. Häuptling Zul'Marosh befindet sich in Zeb'Watha, jenseits des Elrendarsees.", progress = "Habt Ihr mir Zul'Maroshs Kopf gebracht?", completion = "Yo, Mann. Zul'Marosh hat' solch ein Ende verdient. Er brannte Ven'jashis Dorf nieder. Ich hab' viele Amani getötet, bevor sie mich in diesen Käfig steckten. Ich habe etwas im Sand versteckt, es ist mein Geschenk an Euch.\n\nAh... ah, das Gift... es wirkt stärker, Mann. Zeit zu ruhen...", sourceObjectiveStatus = "unverified-source-field" }
quests[8480] = { id = 8480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgelassene Waffen", description = "Die Getriebenen werden mit jedem Tag dreister, {name}. Sie sind mittlerweile gut genug organisiert, um einen Angriff auf den Ankerplatz der Sonnensegel zu verüben.\n\nAls wäre das nicht schon peinlich genug, so hat man bei ihrem Angriff all unsere Waffen zurückgelassen. Bringt mir unsere Waffen zurück, damit wir diesen Halunken zeigen können, wer hier das Sagen hat.", sourceObjective = "Bringt 8 Waffen der Sin'dorei zu Velendris Weißflor im Immersangwald.", progress = "Habt Ihr die zurückgelassenen Waffen an Euch bringen können?", completion = "Gute Arbeit, {name}. Jetzt zeigen wir den Getriebenen mal, aus welchem Holz wir geschnitzt sind!", sourceObjectiveStatus = "unverified-source-field" }
quests[8481] = { id = 8481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wurzel alles Bösen", description = "{name}, dank Euch haben wir eine Möglichkeit ausfindig gemacht, wie wir die Wurzel alles Bösen der Winterfelle beschwören können - den Dämon der Verderbnis, der sie beherrscht!\n\nBringt diese Fackel zum Eingang von Grolnars persönlicher Höhle und stellt sie dort auf. Der Dämon wird sich dadurch zu erkennen geben und nachforschen müssen. Das ist der Moment, in dem Ihr und Eure Verbündeten zuschlagen müsst! Ausschließlich die Essenz des gefallenen Dämonen wird den langwierigen Heilungsprozess des Winterfellstammes in Gang setzen... und die Erlösung der Holzschlundfeste und ihrer Einwohner.", sourceObjective = "Stellt die Fackel zur Dämonenbeschwörung im Eingang von Grolnars Höhle, im Lager der Winterfellfurbolgs auf. Besiegt den Dämon und erlangt die Essenz von Xandivious für Gorn Einauge in der Holzschlundfeste.", progress = "Ihr seid wieder da, {name}... heißt das, dass Ihr den Dämonen besiegt habt?", completion = "Ihr habt... Ihr habt uns gerettet! Euer Sieg über den Dämonen Xandivious gewährleistet die Sicherheit der Holzschlundfeste für die nächsten Jahre. Ihr seid ein wahrer Held unter unsereins.\n\nBitte, nehmt dies mit unserem Segen an. Der Heilungsprozess unter den Furbolgs mag zwar langsam von statten gehen - und der Konflikt auch noch weiterhin bestehen - aber Ihr habt den Winterfellen etwas gegeben, das sie vor diesem Tag nie hatten.\n\nSie haben jetzt eine Überlebenschance.", sourceObjectiveStatus = "unverified-source-field" }
quests[8482] = { id = 8482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belastende Dokumente", description = "Die Dokumente enthalten detaillierte Karten von strategisch wichtigen Gebäuden im Immersangwald. Ihr entdeckt auch die ausführliche Darstellung eines arkanen Sanktums. Überall finden sich Randnotizen in einer Euch unbekannten Sprache.\n\nDa Ihr diese Dokumente bei einem darnassischen Spion gefunden habt, solltet Ihr sie besser zum Hauptmann der Wache bringen - Aeldon Sonnenmal.", sourceObjective = "Bringt die belastenden Dokumente zu Aeldon Sonnenmal auf dem Falkenplatz im Immersangwald.", progress = "Ihr habt etwas für mich? Lasst mich einen Blick darauf werfen.", completion = "Seid Ihr sicher, dass Ihr das bei einem Nachtelfen gefunden habt? Das Geschriebene ist eindeutig zwergisch... \n\nSoweit ich diesen Brief deuten kann, hatte der Verfasser nichts mit der Fehlfunktion zu tun, stattdessen wurde er hierher gesandt, um die Folgen der Katastrophe zu beobachten. Sie bezeichnen unsere Bemühungen als rücksichtslos und gefährlich, aber wer...?\n\nNatürlich! Dieser Gesandte aus Eisenschmiede! Es war ein Fehler von uns, einem Mitglied der Allianz zu vertrauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[8483] = { id = 8483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwergenspion", description = "Hört mir genau zu, {name}. Das ist eine sehr delikate Angelegenheit; obwohl wir den Spion eindeutig identifiziert haben, können wir ihn nicht einfach in aller Öffentlichkeit töten. Eine Gefangennahme kommt auch nicht in Frage, das Risiko einer Flucht wäre einfach zu hoch.\n\nIch möchte, dass Ihr Ausgrabungsleiter Ambossel am Sanktum des Nordens aufsucht und ihn tötet. Geht dabei möglichst unauffällig vor, es soll nicht das Gerücht entstehen, wir hätten einem Spion Zugang zu unserer Stadt gewährt.\n\nBringt mir seinen Kopf als Beweis. Eisenschmiede wird schnell lernen, was es heißt, sich mit den Sin'dorei anzulegen.", sourceObjective = "Bringt den Kopf von Ausgrabungsleiter Ambossel zu Aeldon Sonnenmal beim Falkenplatz im Immersangwald.", progress = "Habt Ihr Euch um den Eindringling gekümmert?", completion = "So, es ist also getan. Hervorragende Arbeit.\n\nWir haben den Waldläufergeneral von der Situation in Kenntnis gesetzt und glaubt mir, die Zwerge werden für ihren Verrat mit Blut bezahlen.\n\nHeute habt Ihr Eurem Volk einen großen Dienst geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8484] = { id = 8484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bemühen um Frieden", description = "Eure Taten gehen weit über die Geschichte eines einfachen Helden hinaus, {name}. Solltet Ihr der Vertreter Eures Volkes sein, dann sind dies diejenigen, mit denen wir, dem Frieden zu Willen, gerne zusammenarbeiten würden.\n\nBitte - bringt dies als Zeichen unseres Friedens zu dem Zwergenkönig, der in einem Berg aus Eisen lebt; ich glaube man nennt diese Stadt Eisenschmiede. In vergangenen Zeiten hatte er im Namen seiner Allianz versucht, mit uns Kontakt aufzunehmen. Es bietet sich jetzt also an, Euch als Schlüssel hinsichtlich der Friedensbemühungen Eurer Allianz zu betrachten.", sourceObjective = "Bringt das Friedensangebot der Holzschlundfeste zu König Magni Bronzebart in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8485] = { id = 8485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Bemühen um Frieden", description = "Eure Taten gehen weit über die Geschichte eines einfachen Helden hinaus, {name}. Solltet Ihr der Vertreter Eures Volkes sein, dann sind dies diejenigen, mit denen wir, dem Frieden zu Willen, gerne zusammenarbeiten würden.\n\nBitte, bringt dies als Zeichen unseres Friedens zu dem Kriegshäuptling der Orcs, der in den Landen von Durotar lebt; ich glaube man nennt die Stadt Orgrimmar. In vergangenen Zeiten hatte er im Namen seiner Horde versucht, mit uns Kontakt aufzunehmen. Es bietet sich jetzt also an, Euch als Schlüssel hinsichtlich der Friedensbemühungen Eurer Horde zu betrachten.", sourceObjective = "Bringt das Friedensangebot der Holzschlundfeste zu Shok Narnes in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8486] = { id = 8486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Instabilität", description = "Es wurde Zeit, dass dieser Schwachkopf Caidanis endlich jemanden hierher gesandt hat.\n\nIch habe davor gewarnt, die Ladungen beim Sanktum des Westens zu erhöhen! Jetzt ist einer unserer Energiewandler zerstört und Arkangespenster strömen aus dem Sanktum!\n\nIhr müsst Euch um diese Kreaturen kümmern, bevor wir überhaupt jemanden für die Reparaturarbeiten hinein lassen können. Beeilt Euch!", sourceObjective = "Leybewahrerin Velania möchte, dass Ihr 5 Managespenster und 5 Manapirscher tötet.", completion = "Danke, {name}. Jetzt, wo wir die Gespenster unter Kontrolle haben, können wir das Ganze von jemandem begutachten lassen. Hoffentlich handelt es sich nicht um bleibende Schäden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8487] = { id = 8487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Erde", description = "Bevor Arthas und seine Armee der Geißel auf die Idee kamen, auf ihrem Weg nach Silbermond hier durchzumarschieren, war dies ein voll funktionstüchtiges arkanes Sanktum.\n\nJetzt hat es in etwa den gleichen Nutzen wie der Rest, der zur Todesschneise gehört. Der Grund ist besudelt, Untote werden davon angezogen und die Energie der Leylinien wurde komplett unterbrochen.\n\nWas ich jetzt herausfinden will, {name}, ist, ob man diese Besudelung wieder umkehren kann oder nicht. Sammelt Erdproben dieser Gegend für mich, damit ich sie untersuchen kann. Vielleicht können wir mit der Zeit den normalen Zustand wieder herstellen.", sourceObjective = "Lehrling Mirveda beim Sanktum des Ostens im Immersangwald möchte, dass Ihr 8 besudelte Erdproben einsammelt.", progress = "Habt Ihr die von mir benötigten Erdproben eingesammelt, {name}?", completion = "Ausgezeichnet. Ich werde einen Zauber auf die Proben wirken, damit ich die Besudelung besser analysieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[8488] = { id = 8488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliche Ergebnisse", description = "Irgendetwas ist faul, {name}. Ich spüre die Gegenwart der Geißel. Macht Euch zum Kampf bereit!", sourceObjective = "Sprecht mit Lehrling Mirveda und beschützt sie dann vor dem Angriff der Geißel.", progress = "Ist es vorbei? Sind sie alle weg?", completion = "Es ist hoffnungslos, {name}. Die Beschaffenheit der Erde selbst hat sich verändert... die Besudelung ist unabänderlich. Vielen Dank für Eure Unterstützung. Ich muss Euch noch um einen letzten Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8489] = { id = 8489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein intakter Wandler", description = "Dieser Gegenstand scheint einer der Arkanwandler zu sein, von denen Leybewahrerin Velania sprach. Er blieb vom Feuer verschont, vielleicht kann sie ja etwas damit anfangen.", sourceObjective = "Bringt den intakten Arkanwandler zu Leybewahrerin Velania.", sourceObjectiveStatus = "unverified-source-field" }
quests[8490] = { id = 8490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederaufladen der Verteidigung", description = "Uralte Runensteine hielten einst eine Schutzbarriere an der Grenze des Immersangs aufrecht.Viele wurden während Arthas' Angriff zerstört, andere wurden gestohlen.\n\nVon den drei, die übrig geblieben sind, konnte nur dieser seine Macht bewahren. Der Runenstein des Ostens könnte jedoch noch gerettet werden.\n\nNehmt diesen Kristall und flößt dem Runensteins des Ostens seine Energie ein. Der Vorgang sollte nur einen Moment benötigen. Doch Vorsicht, die Energien werden auch in der Umgebung befindliche Kreaturen der Geißel anziehen. Sie dürfen den Runenstein auf keinen Fall zerstören!", sourceObjective = "Platziert den energieerfüllten Kristall beim Runenstein des Ostens und verteidigt ihn 1 Minute lang vor der Geißel. Bringt den energieerfüllten Kristall anschließend zu Runenwächter Deryan im Immersangwald, um Eure Belohnung zu erhalten.", progress = "Konntet Ihr den Runenstein mit Energie versorgen, {name}?", completion = "Hervorragend. Die Verteidigungsmaßnahmen sollten die Geißel noch ein wenig länger in Schach halten. Vielen Dank für Eure Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8491] = { id = 8491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pelzjagd", description = "Die Bachtatzen in dieser Region sind für ihre hochwertigen Pelze bekannt. Selbst Nachtelfenabschaum dringt in unsere Länder ein, um hier zu wildern.\n\nDie andauernden Scharmützel mit den Amani haben unsere Versorgung mit Ausrüstung stark strapaziert. Leider finden unsere Waldläufer aufgrund dessen kaum Zeit für die Pelzjagd. Vielleicht möchtet Ihr uns eine helfende Hand reichen und einige Bachtatzenfelle beschaffen, eine handgefertigte Rüstung wäre Euer Lohn. Sucht in den Wäldern nördlich von hier nach Bachtatzenpirschern.", sourceObjective = "Velan Lichteiche in Morgenluft im Immersangwald möchte, dass Ihr ihm 6 Bachtatzenfelle bringt.", progress = "Ihr seid schon zurück? Habt Ihr die Pelze?", completion = "Die werden ihren Zweck erfüllen, {name}. Nehmt dieses Rüstungsteil als Belohnung. Mit den Pelzen, die Ihr mir gebracht habt, werde ich noch mehr herstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8492] = { id = 8492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Kupferbarren!", description = "Hey, {class}, Ihr seht tauglich genug aus, um zu den Kriegsanstrengungen beizutragen! Wir brauchen jede Hilfe, die wir bekommen können, um die benötigten Vorräte für den Krieg in Ahn'Qiraj zusammenzutragen. Heute ist Euer Glückstag.\n\nIch sammle Kupferbarren in Stapeln zu je 20 Stück. Der Zweck ist die Mühe wert, was denkt Ihr? Sicherlich wollt Ihr die Allianz unterstützen!", sourceObjective = "Bringt 20 Kupferbarren zu Unteroffizier Steinbraue im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8493] = { id = 8493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Kupferbarren!", description = "Wieder zurück, {class}? Exzellent! Solltet Ihr noch mehr Stapel Kupferbarren aufbringen können, wir benötigen noch immer welche für die Vorbereitungen des Krieges in Ahn'Qiraj. Wie sieht's aus, seid Ihr dabei?", sourceObjective = "Bringt 20 Kupferbarren zu Unteroffizier Steinbraue beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8494] = { id = 8494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Eisenbarren!", description = "Ihr da, seid gegrüßt, <Herr Modenarr/Frau Modenärrin>, was für eine Augenweide Ihr doch seid. Solltet Ihr es, während Ihr auf \"Abenteuern\" wart, noch nicht gehört haben: die Allianz macht sich für den Krieg in Ahn'Qiraj bereit und braucht dringend Eisenbarren... eine ganze Menge davon. Bringt sie in Stapeln zu je 20 Stück zu mir. Wir können doch auf Euch zählen, oder, {class}?", sourceObjective = "Bringt 20 Eisenbarren zu Korporal Schwarz im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8495] = { id = 8495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Eisenbarren!", description = "Schon wieder da? Hört auf, mich meine geringe Meinung von Euch noch einmal überdenken zu lassen, {class}, Ihr macht mich ja ganz gefühlsduselig. Naja, wie Ihr sehen könnt, haben wir noch immer nicht genug Eisenbarren für die Herstellung aller Waffen, Rüstungen, Dampfpanzer und was auch immer für diese Käferjagd noch gebraucht wird. Könntet Ihr vielleicht noch einmal 20 Eisenbarren während Eurer Abenteuerei in Zul'Gurub, oder wo Ihr Bengel Euch dieser Tage sonst noch herumtreibt, besorgen?", sourceObjective = "Bringt 20 Eisenbarren zu Korporal Schwarz beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8496] = { id = 8496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbände für den Feldeinsatz", description = "Nach den neusten Verlusten, die wir hinnehmen mussten, gehen unsere Vorräte an Verbänden für das Schlachtfeld gefährlich zur Neige. Besorgt Euch eine Ladung an Vorräten für Erste Hilfe und bringt sie zu Windruferin Prachthorn auf Burg Cenarius.", sourceObjective = "Bringt 30 schwere Runenstoffverbände, 30 schwere Seidenverbände und 30 schwere Magiestoffverbände zu Windruferin Prachthorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz X, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8497] = { id = 8497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenüberlebenspaket", description = "Seitdem ständig neue Rekruten auf Burg Cenarius eintreffen, stehen wir vor dem Problem, sie in der Wüste am Leben zu erhalten. Der ständige Wasserentzug und die zahlreichen giftigen Kreaturen in dieser Gegend sind eine ernstzunehmende Gefahr für die unerfahren Soldaten. Sammelt alles, was notwendig ist, um ein Wüstenüberlebenspaket zusammenzustellen und bringt die erforderlichen Vorräte zu Calandrath auf Burg Cenarius.", sourceObjective = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8498] = { id = 8498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtschlachtbefehle", description = "Unsere Späher haben berichtet, dass die Anführer des Schattenhammers neue Schlachtbefehle ausgegeben haben. Die Befehle wurden von Propheten des Schattenhammers unter schwerem Geleitschutz verteilt. Fangt die Schlachtbefehle ab und bringt sie zu Kommandant Mar'alith.", sourceObjective = "Beschafft Euch die Schlachtbefehle des Schattenhammers und bringt sie zu Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch den taktischen Einsatz X, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8499] = { id = 8499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Thoriumbarren!", description = "Es ist äußerst freundlich, dass Ihr Euch nach den Bedürfnissen der Allianz erkundigt. Zusätzlich zu all den anderen Sammelaktionen, die gerade im Gange sind, benötigen wir noch jede Menge Thoriumbarren. Damit wurde ich beauftragt. Thorium wird der Herstellung von vielerlei Kriegsmaterialien dienen, vor allem aber dem Aufbau eines Bataillons von Dampfpanzern, die nach ihrer Fertigstellung per Lufttransport nach Silithus gebracht werden sollen. Könntet Ihr uns bei diesem Unterfangen behilflich sein, {class}?", sourceObjective = "Bringt 20 Thoriumbarren zu Dame Doppelzopf im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8500] = { id = 8500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Thoriumbarren!", description = "Schön, Euch wiederzusehen, {name}. Ich hoffe, es ist Euch gut ergangen. Es stimmt, wir benötigen noch immer Thoriumbarren. Solltet Ihr welche entbehren können, ich sammle sie hier für die Kriegsvorbereitungen von Ahn'Qiraj.", sourceObjective = "Bringt 20 Thoriumbarren zu Dame Doppelzopf beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8501] = { id = 8501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Stecher des Ashischwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die fliegenden Stecher des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Stecher des Ashischwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XII, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8502] = { id = 8502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Arbeiter des Ashischwarms", description = "Die Anwesenheit der Silithiden in diesem Gebiet stellt eine immer stärker werdende Bedrohung für unsere Operationen dar. Ihr wurdet ausgewählt, um an einem Angriff auf den Bau des Ashischwarms teilzunehmen. Eure Hauptziele sind die Arbeiter des Ashischwarms.\n\nErstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Arbeiter des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz III, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8503] = { id = 8503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Würgetang!", description = "So {class}, habe ich Euch schon von all den wunderbaren Verwendungszwecken erzählt, die Würgetang bietet? Ja? Oh, na dann... wir brauchen auf jeden Fall eine Menge davon, und wenn ich eine Menge sage, dann meine ich eine große Menge! Meint Ihr, dass Ihr uns helfen könntet? Ich weiß, dass das bedeutet, dass Ihr daraus nichts Tolles für Euch selbst herstellen könnt, aber es ist für einen guten Zweck!", sourceObjective = "Bringt 20 Stück Würgetang zu dem Gefreiten Drechselknacks im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8504] = { id = 8504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Würgetang!", description = "Hallo Ihr... warum seid Ihr nochmal hier? Ah... natürlich, {name}! Ihr seid gekommen, um nachzusehen, ob ich noch mehr Würgetang brauche, oder? Na dann ist heute Euer Glückstag, denn die Antwort auf diese wichtige Frage lautet eindeutig JA! Könntet Ihr vielleicht noch einmal zwanzig mehr sammeln?", sourceObjective = "Bringt 20 Stück Würgetang zu dem Gefreiten Drechselknacks beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8505] = { id = 8505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht lila Lotus!", description = "{class}, lila Lotus ist eine Pflanze, die vielfach verwendet werden kann. Ich bin hier im Auftrag der Allianz und verantwortlich dafür, dass die gesammelten Pflanzen sicher aufbewahrt und ihrem vorgesehenen Verwendungszweck im Rahmen unserer Kriegsbemühungen zugeführt werden.\n\nIch würde Euch gerne damit beauftragen durch die Welt zu ziehen und zu mir zurückzukehren, sobald Ihr einige dieser Pflanzen gesammelt habt. Wäre das machbar?", sourceObjective = "Bringt 20 lila Lotus zu Meister Nachtweise im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8506] = { id = 8506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr lila Lotus!", description = "Seid gegrüßt, {class}. Unsere Sammlung wächst zwar, aber wir brauchen auch weiterhin noch lila Lotus. Wenn Ihr glaubt, noch mehr dieser Pflanzen beschaffen zu können, dann bitte ich Euch inständig dies zu tun und damit anschließend zu mir zurückzukehren.", sourceObjective = "Bringt 20 lila Lotus zu Meister Nachtweise beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8507] = { id = 8507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felddienst", description = "Seid gegrüßt, {name}. Bevor ich Euch mit umfassenderen Aufgaben in diesem Krieg beauftrage, müsst Ihr Euren Anteil am Felddienst leisten.\n\nIhr könnt die Eisenschmiedebrigade von Hauptmann Rußschmied außerhalb des Zoraschwarmbaus finden.\n\nErstattet ihm oder seinem Leutnant, Janela Starkhammer, Bericht und kommt dann wieder zu mir. Ich werde wichtigere Anweisungen für Euch bereithalten.\n\nOh, bitte erweist uns den Gefallen und haltet Euch von der Orgrimmarlegion fern. Wir sind gezwungen die beiden Streitkräfte aufgrund gegenseitiger Feindseligkeit auseinander zu halten.", sourceObjective = "Erstattet am Posten der Eisenschmiedebrigade beim Zoraschwarmbau Bericht. Bereitet Eure nicht unterzeichneten Felddienstpapiere vor, lasst sie von Hauptmann Rußschmied unterzeichnen und kehrt zu Windrufer Kaldon auf Burg Cenarius in Silithus zurück.\n\nHinweis: das Heilen oder Wirken von begünstigenden Zaubern auf ein Mitglied der Eisenschmiedebrigade wird Euch für den PvP-Kampf markieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[8508] = { id = 8508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felddienstpapiere" }
quests[8509] = { id = 8509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Arthas' Tränen!", description = "Ich möchte nicht lange darum herum reden, {class}. Die Allianz benötigt eine große Menge an Arthas' Tränen für die Kriegsanstrengungen von Ahn'Qiraj. Fragt mich nicht für was; ich befolge nur Anweisungen. Trotzdem würde ich Euch gerne bitten, so viele dieser Pflanzen wie möglich zu sammeln und sie anschließend hierher zu mir zu bringen. Würdet Ihr das tun?", sourceObjective = "Bringt 20 Arthas' Tränen zu Stabsfeldwebel Germaine im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8510] = { id = 8510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Arthas' Tränen!", description = "Ok, es sieht so aus, als ob ich noch mehr Arthas' Tränen benötigen würde. Ich könnte mir vorstellen, dass Ihr sie dort wiederfindet, wo Ihr sie auch schon das letzte Mal für mich gesammelt habt. Umso schneller wir sie beisammen haben, desto schneller können wir unsere Offensive in Ahn'Qiraj beginnen.\n\nHelft Ihr uns noch einmal, {class}?", sourceObjective = "Bringt 20 Arthas' Tränen zu Stabsfeldwebel Germaine beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8511] = { id = 8511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht leichtes Leder!", description = "Wir Steinschinders können auf eine lange Geschichte der Kürschnerei zurückblicken, {class}. Deshalb hat die Allianz auch meine Familie damit beauftragt, bei der Sammlung von leichtem Leder für die Kriegsanstrengungen von Ahn'Qiraj mitzuhelfen. Ich achte darauf, dass das Leder vernünftig gegerbt wird. Was danach daraus gemacht wird, weiß ich nicht. Wir brauchen jedoch Eure Hilfe.\n\nDa ich wegen meiner Arbeit hier bleiben muss, brauche ich Euch, um die Häute zu beschaffen und sie anschließend zu mir zu bringen. Was meint Ihr <Junge/Mädel>, seid Ihr dabei?", sourceObjective = "Bringt 10 Einheiten leichtes Leder zu Bonnie Steinschinder im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8512] = { id = 8512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr leichtes Leder!", description = "Schön, Euch wiederzusehen, {name}. Es scheint, als würden wir noch mehr leichtes Leder für die Herstellung verschiedenster Kriegsmaterialien benötigen. Es wäre großartig, wenn ihr mir noch einmal einen Stapel mit zehn Stücken bringen könntet.", sourceObjective = "Bringt 10 Einheiten leichtes Leder zu Bonnie Steinschinder beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8513] = { id = 8513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mittleres Leder!", description = "Ja, <mein Herr/meine Dame>, ich wurde mit der Sammlung und Aufbewahrung des mittleren Leders für die Kriegsvorbereitungen beauftragt. Solltet Ihr über die Mittel verfügen, um mittleres Leder besorgen zu können, woher auch immer, dann bringt es bitte zu mir. Ich könnte mit Sicherheit etwas Unterstützung gebrauchen, wenn Ihr Zeit habt.", sourceObjective = "Bringt 10 Einheiten mittleres Leder zu dem Gefreiten Porter im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8514] = { id = 8514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr mittleres Leder!", sourceObjective = "Bringt 10 Einheiten mittleres Leder zu dem Gefreiten Porter beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8515] = { id = 8515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht dickes Leder!", description = "Junge, Junge, das wird großartig! {class}, die Vorbereitungen für den Krieg in Ahn'Qiraj sind in vollem Gange und man hat mich damit beauftragt sämtliche Ladungen an dickem Leder zu überwachen, die hier abgeliefert werden. Wir fertigen zahlreiche Dinge daraus an, aber zuallererst brauchen wir eine große Menge davon. Eine gewaltige Menge! Jetzt zu Euch.\n\nGlaubt Ihr, dass Ihr losziehen und mir einen fetten Stapel dickes Leder beschaffen könntet? Ja, wirklich?!", sourceObjective = "Bringt 10 Einheiten dickes Leder zu Marta Feinspindel im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8516] = { id = 8516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr dickes Leder!", sourceObjective = "Bringt 10 Einheiten dickes Leder zu Marta Feinspindel beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8517] = { id = 8517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Leinenverbände!", description = "Der Krieg in Ahn'Qiraj wird lange und blutig sein. Es ist sehr weise, dass die Allianz Eure Hilfe und die von anderen Euresgleichen in Anspruch nimmt, um vorerst die benötigten Mittel zu erstellen, anstelle sich sofort in den Konflikt zu stürzen.\n\nIch wurde mit dem Sammeln von Leinenverbänden für den Krieg beauftragt und hoffe nun, dass Ihr mir bei dieser Aufgabe zu Hand gehen werdet. Wir brauchen so viele Verbände wie möglich. Es ist keine leichte Aufagbe, ich weiß, aber wenigstens lassen sich Leinenverbände am einfachsten herstellen. Seid Ihr dabei, {class}?", sourceObjective = "Bringt 20 Leinenverbände zu Schildwache Silberwolke im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8518] = { id = 8518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Leinenverbände!", description = "Ich bin immer wieder von der Selbstlosigkeit überrascht, die an den Tag gelegt wird, denn andere würden an gleicher Stelle reine Selbstsucht walten lassen. {class}, ich brauche immer noch eine gewisse Anzahl an Leinenverbänden, um meinen Auftrag hier zu erfüllen. Würdet Ihr mir noch einmal beim Sammeln dieser Verbände helfen?", sourceObjective = "Bringt 20 Leinenverbände zu Schildwache Silberwolke beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8519] = { id = 8519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Spielfigur auf dem Schachbrett der Ewigkeit", description = "Als Ihr Eure Fassung wieder gewinnt und Ihr Euren Blick fokussiert, fällt Euch auf, dass sich etwas innerhalb des Kristalls bewegt. Nach genauerer Betrachtung wird Euch klar, dass Ihr gerade in die Vergangenheit seht... eine Erinnerung... seit langer Zeit vergessen.", sourceObjective = "Lernt so viel Ihr könnt über die Vergangenheit, sprecht dann mit Anachronos in den Höhlen der Zeit in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[8520] = { id = 8520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Seidenverbände!", description = "Mit dem immer näherrückenden Krieg in Ahn'Qiraj gilt es alles Erdenkliche zu tun, um unsere Soldaten mit allem zu versorgen, das sie brauchen werden. Wir kümmern uns hier genau um diese Sache. Ich bin verantwortlich für das Ansammeln von Seidenstoffverbänden.\n\nGlaubt Ihr, dass Ihr mir dabei helfen könntet, {class}?", sourceObjective = "Bringt 20 Seidenverbände zu Schwester Steinfeld im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8521] = { id = 8521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Seidenverbände!", sourceObjective = "Bringt 20 Seidenverbände zu Schwester Steinfeld beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8522] = { id = 8522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Runenstoffverbände!", description = "{class}, stellt die Verdienste des Krieges in Frage, wenn Ihr wollt, er hat jedoch schon längst begonnen. Seht Euch bei Eurer Familie oder Euren Freunden um und fragt Euch dann, was es ist, das Ihr tun könnt, um im Fall der Fälle zu ihrem Überleben beizutragen.\n\nIch sammle hier Runenstoffverbände jeglicher Herkunft. Würdet Ihr gerne welche spenden?", sourceObjective = "Bringt 20 Runenstoffverbände zu Bewahrer Mondschatten im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8523] = { id = 8523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Runenstoffverbände!", description = "Wir treffen also erneut aufeinander, um wichtige Angelegenheiten zu besprechen, {class}. Ich möchte Euch noch einmal für Eure bisherigen Bemühungen danken; nicht jeder ist so selbstlos wie Ihr. Es gibt jedoch noch mehr zu tun.\n\nWürdet Ihr noch einmal Runenstoffverbände für mich sammeln gehen und sie dann zu mir bringen, {name}?", sourceObjective = "Bringt 20 Runenstoffverbände zu Bewahrer Mondschatten beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8524] = { id = 8524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Regenbogenflossenthunfisch!", description = "Hey, Ihr da! Wenn ich zu Euch sagen würde 'Sollten Soldaten nicht etwas zu essen haben, wie jeder andere auch?', dann würdet Ihr natürlich 'Ja!' sagen. Da stimme ich 110% mit Euch überein! Schön, dass wir uns einig sind. Es gibt nur eine Sache, um die ich Euch gerne bitten würde: zieht los, fischt eine ordentliche Menge Regenbogenflossenthunfische, kocht diese dann und bringt sie zu mir zurück. Mmm, mmm, ich kann es bereits schmecken.", sourceObjective = "Bringt 20 Regenbogenflossenthunfische zu Gastronom Glitschko im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8525] = { id = 8525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Regenbogenflossenthunfisch!", description = "Was! Ihr seid schon wieder da? Naja, in der Kürze liegt ja bekanntlicherweise die Würze... ich als Gnom muss es ja wissen, Gastronom Glitschko genaugenommen! Ihr seid also wieder da, um auch weiterhin auszuhelfen? Nun, ich kann es Euch nicht verdenken. Liebt Ihr nicht ganz einfach den Duft von all diesem Essen? <lechz>\n\nGenug getrödelt! Geht jetzt los und fangt mehr Regenbogenflossenthunfisch für mich!", sourceObjective = "Bringt 20 Regenbogenflossenthunfische zu Gastronom Glitschko beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8526] = { id = 8526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht geröstete Raptoren!", description = "Oh, wie geht's, {class}? Ich sehe, dass Ihr eventuell beim Sammeln von Lebensmittelvorräten für den aufziehenden Krieg in Ahn'Qiraj mithelfen möchtet. Mein Vater hat sich wohl gedacht, dass es eine gute Lernerfahrung für mich wäre, wenn ich mich als freiwillige Aushilfe hier melde. Ein großer Fehler. Ich esse noch nicht einmal Fleisch.\n\nEgal, wenn Euch danach ist, dann könntet Ihr mir eine Menge gerösteter Raptoren bringen. Anscheinend ist das genau das, wonach Soldaten verlangen.", sourceObjective = "Bringt 20 geröstete Raptoren zu Sarah Sorgenpfeifer im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8527] = { id = 8527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr geröstete Raptoren!", description = "Hallo nochmal, {class}. Wie ich sehen kann, macht Euch die Sache richtig Spaß. Meiner Vermutung nach wollt Ihr mir also nochmal zwanzig geröstete Raptoren bringen. Großartig. Dann macht mal. Wir sehen uns, wenn Ihr wieder zurück seid.", sourceObjective = "Bringt 20 geröstete Raptoren zu Sarah Sorgenpfeifer beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8528] = { id = 8528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht Tüpfelgelbschwänze!", description = "Das Sammeln von gekochtem Fisch mag zwar nicht sehr heldenhaft erscheinen, aber Ihr solltet die Wichtigkeit von guten Vorbereitungen nicht unterschätzen, {class}. Soldaten müssen eben essen, wie jeder andere auch. Wir leisten hierfür unseren Teil, um sicherzustellen, dass sie mit allem versorgt sind, das sie brauchen, sobald der Krieg in Ahn'Qiraj beginnt.\n\nFolglich sorge ich hier für die Einlagerung von Tüpfelgelbschwänzen, eine vielseitige Nahrungsressource, die sich gut lagern lässt und auf verschiedenste Art und Weise zubereitet werden kann. Der Geruch ähnelt zudem nicht dem von anderen Salzwasserfischen. Wollt Ihr mir bei dieser Unternehmung behilflich sein?", sourceObjective = "Bringt 20 Tüpfelgelbschwänze zu Jägerin Flinkbach im Militärviertel in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[8529] = { id = 8529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr Tüpfelgelbschwänze!", description = "Wenn Ihr noch immer gewillt seid, dann würde ich Euch gerne aussenden, um einen weiteren Schwung Tüpfelgelbschwänze zu beschaffen, {name}. Ich vermute, dass es nach der Erfahrung, die Ihr beim ersten Mal gesammelt habt, diesmal wesentlich schneller und einfacher für Euch sein wird. Seid Ihr dabei?", sourceObjective = "Bringt 20 Tüpfelgelbschwänze zu Jägerin Flinkbach beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8530] = { id = 8530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht sengende Kernsteine!", description = "{class}, ich brauche Eure Hilfe. Im Geschmolzenen Kern gibt es diese Steine, sengende Kernsteine, um genau zu sein, die wir für die Kriegsanstrengungen von Ahn'Qiraj einsammeln müssen. Mir wurde gesagt, dass unsere Schmiede und Ingenieure eine gute Verwendung für sie haben. Jetzt kommt Ihr ins Spiel. Ich brauche Euch, damit Ihr zum Geschmolzenen Kern geht und so viele dieser Kernsteine wie Ihr könnt einsammelt. Natürlich werdet Ihr dafür neununddreißig Eurer engsten Freunde mit Euch nehmen wollen.", sourceObjective = "Bringt 50 sengende Kernsteine zu Kommandant Hammerkraft beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8531] = { id = 8531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Allianz braucht mehr sengende Kernsteine!", description = "Danke, dass Ihr nochmal vorbeigeschaut habt, {name}. Wenn Euch und Euren Freunden noch der Sinn danach steht, könntet Ihr bitte ein weiteres Mal zum Geschmolzenen Kern gehen und noch mehr der Kernsteine einsammmeln? Würdet Ihr das tun?", sourceObjective = "Bringt 50 sengende Kernsteine zu Kommandant Hammerkraft beim Landeplatz in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[8532] = { id = 8532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Kupferbarren!", description = "Ich bin froh, dass Ihr Euch entschieden habt hier auszuhelfen. Nicht jeder würde das tun, deshalb ist es auch wichtig, dass Ihr wirklich versteht, was ich hier brauche. Kupferbarren, nicht Kupfererz. Wir haben weder die Zeit, noch genügend Leute, um das Material hier selbst zu verhütten, wenn Ihr also so freundlich wäret und diesen Vorgang für uns übernehmen würdet. Man würde Eure Mühen an den richtigen Stellen zur Kenntnis nehmen. Was sagt Ihr dazu, {class}?", sourceObjective = "Bringt 20 Kupferbarren zu Minenarbeiter Kromwell im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8533] = { id = 8533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Kupferbarren!", description = "Schon wieder da? Ihr werdet in kürzester Zeit noch zum richtigen Bergarbeiter, {class}. So, Ihr wisst Bescheid. Zieht los, baut jede Menge Kupfererz ab, verhüttet es in Barren und bringt diese dann hierher zu mir. Ich weiß, dass Ihr es könnt, die Frage ist nur, ob Ihr dazu auch gewillt seid?", sourceObjective = "Bringt 20 Kupferbarren zu Minenarbeiter Kromwell in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8534] = { id = 8534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späherbericht des Zoraschwarms", description = "Wir haben unsere besten Späher bis weit in die Schwarmbauten der Silithiden ausgesendet. Späherin Azenel hat die Aktivitäten der Silithiden im Zoraschwarm nun schon seit Tagen beobachtet. Findet sie und besorgt Euch einen schriftlichen Bericht. Wir müssen so schnell wie möglich auf diese Informationen reagieren können, {name}.", sourceObjective = "Setzt Euch mit der cenarischen Späherin Azenel innerhalb des Zoraschwarmbaus in Verbindung und bringt den Späherbericht des Zoraschwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VI, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8535] = { id = 8535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weißgrauer Templer", description = "Die Schattenhammerkultisten und die von ihnen verehrten Elementarfürsten, stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj, können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen weißgrauen Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", sourceObjective = "Beschwört und vernichtet einen weißgrauen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz IV, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8536] = { id = 8536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irdener Templer", description = "Die Schattenhammerkultisten und die von ihnen verehrten Elementarfürsten stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen irdenen Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", sourceObjective = "Beschwört und vernichtet einen irdenen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz III, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8537] = { id = 8537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Purpurroter Templer", description = "Die Schattenhammerkultisten und die von ihnen verehrten Elementarfürsten stellen eine dauerhafte Bedrohung für unsere Operationen in Silithus dar. Trotz der neuen Gegnermassen in Ahn'Qiraj können wir es uns nicht erlauben, unsere Wachposten und Einsätze gegen den äußeren Feind zu verringern.\n\nFindet einen Weg, um einen purpurroten Templer auf unsere Existenzebene zu beschwören und zerstört ihn.", sourceObjective = "Beschwört und vernichtet einen purpurroten Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz II, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8538] = { id = 8538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die vier Fürsten", description = "Die Verbindungen zwischen dem Schattenhammer und dem abyssischen Rat scheinen bedeutsamer zu sein, als wir erwartet hätten.\n\nMan sagt, dass die namhaften Elementare, bekannt als die abyssischen Fürsten, ein Teil der treibenden Kräfte hinter den Kultisten des Schattenhammers sind. Findet einen Weg, um die vier abyssischen Fürsten auf unsere Existenzebene zu locken und zerstört sie!\n\nIhr habt in den vorangegangenen Einsätzen Eigeninitiative und Mut bewiesen, daher wurdet Ihr für den heutigen Auftrag ausgewählt. Wir sind sehr zuversichtlich, dass Ihr auch diesen Einsatz meistern werdet.", sourceObjective = "Findet einen Weg, um den Fürst der Asche, den Fürst der Tiefen, den Fürst der Stürme und den Fürst der Splitter zu beschwören und zu vernichten. Erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz V, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8539] = { id = 8539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziel: Schwestern des Zoraschwarms", description = "Es wurde Verstärkung für den Angriff auf den Bau des Zoraschwarms angefordert. Man hat Euch ausgewählt, um die Schwestern des Zoraschwarms anzugreifen. Erstattet bei Kommandant Mar'alith Bericht, sobald Ihr Eure Aufgabe beendet habt.", sourceObjective = "Tötet 30 Schwestern des Zoraschwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz V, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8540] = { id = 8540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stiefel für die Wache", description = "Die berittene Einheit der Wache von Burg Cenarius hat kaum noch Vorräte an verschnörkelten Mithrilstiefeln. Beschafft Euch eine Ladung und bringt sie sofort zu Hauptmann Vish Kozus auf Burg Cenarius.", sourceObjective = "Bringt 3 Paar verschnörkelte Mithrilstiefel zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz II, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8541] = { id = 8541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleifsteine für die Wache", description = "Die Wache von Burg Cenarius hat kaum noch Vorräte an Schleifsteinen. Beschafft Euch eine Ladung und bringt sie sofort zu Hauptmann Vish Kozus auf Burg Cenarius.", sourceObjective = "Bringt 10 verdichtete Schleifsteine, 10 robuste Schleifsteine und 10 schwere Schleifsteine zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz III, um diese Aufgabe abschließen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[8542] = { id = 8542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Zinnbarren!", description = "Lok-Tar, {race}! Sicher habt Ihr schon von dem aufziehenden Krieg gegen die Insekten in Ahn'Qiraj gehört. Doch bevor wir losziehen, hat der Kriegshäuptling vorerst entschieden sogenannte 'Vorbereitungen' zu treffen. Obwohl ich viel lieber stumpfe Waffen schärfen oder Rüstungen wieder in Form bringen würde, ist mir die ehrenvolle Aufgabe übertragen worden, die Sammlung von Zinnbarren zu überwachen.\n\nDas bedeutet, dass ich Eure Hilfe brauche und dass Ihr für mich losziehen müsst, um Zinnbarren aufzutreiben und hierher zu mir zu bringen. Ich denke, dass ich mehr brauchen werde, als ich zählen kann.", sourceObjective = "Bringt 20 Zinnbarren zu Grunzer Maug im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8543] = { id = 8543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Zinnbarren!", description = "Sehr gut, ich denke, Ihr versteht den Ernst des Krieges. Das Warten auf den Auftakt macht mich ganz nervös, was bedeutet, dass ich sehr verärgert sein werde, wenn Ihr mir nicht schneller mehr der Ressourcen bringt. Vielleicht sollte ich mich auch ganz einfach an Euch üben.\n\nHarr! Besser nicht, wer sollte mir denn sonst die Zinnbarren bringen?", sourceObjective = "Bringt 20 Zinnbarren zu Grunzer Maug in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8544] = { id = 8544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiftung des Eroberers", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", sourceObjective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Nacht, 5 Steinskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8545] = { id = 8545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Mithrilbarren!", description = "{class}, der Krieg rückt näher und das Einzige, was wir tun können, ist uns darauf vorzubereiten. Hierbei können wir uns gegenseitig helfen. Seht Ihr, ich wurde mit der Sammlung von Mithrilbarren beauftragt, die wir zur Herstellung von allerlei Kriegsbedarf benötigen. Es fehlt noch eine ganze Menge!\n\nSo, ich hoffe, Ihr zieht jetzt los, baut so viel Mithrilerz ab, wie Ihr könnt und verhüttet es zu Mithrilbarren. Könntet Ihr das für uns tun?", sourceObjective = "Bringt 20 Mithrilbarren zu Schlachtrufer T'kelah im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8546] = { id = 8546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Mithrilbarren!" }
quests[8547] = { id = 8547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Marsilla Morgenstern auf dem Falkenplatz einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt den Geschenkgutschein des Falkenplatzes zu Marsilla Morgenstern auf dem Falkenplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[8548] = { id = 8548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Kriegsfreiwilligen", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, {name}.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", sourceObjective = "Bringt 5 cenarische Gefechtsabzeichen, 3 cenarische Versorgungsabzeichen und 7 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8549] = { id = 8549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Friedensblumen!", description = "Man sagt, dass sich jede Generation einer bestimmten Prüfung stellen muss. Ich fürchte, dass der Krieg von Ahn'Qiraj genau das Ereignis ist, in dem unser Eifer auf die Probe gestellt wird. Wir bereiten uns deshalb vor, und finden dabei heraus, was uns wirklich ausmacht.\n\nIch habe mich freiwillig gemeldet, um der Horde beim Sammeln von so vielen Friedensblumen wie möglich zu helfen. Diese können dann in Tränke für den Kriegseinsatz verarbeitet werden. Ich hoffe, dass Ihr hier seid, um mir behilflich zu sein. Wenn ja, dann bringt mir eine gute Menge dieser Pflanzen. Werdet Ihr mich unterstützen, {class}?", sourceObjective = "Bringt 20 Friedensblumen zu der Kräuterkundigen Stolzfeder im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8550] = { id = 8550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Friedensblumen!" }
quests[8551] = { id = 8551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truhe des Kapitäns", description = "Früher hab ich ein Schiff von hier bis ganz nach Ratschet, in Kalimdor gesegelt. Ich war ein erfolgreicher Kapitän mit einem einwandfreien Ruf.\n\nBis...\n\nDiese verfluchten Meeresriesen mich ruinierten! Sie haben mein Schiff zerschmettert, meine Crew umgebracht und mich in ein Rettungsboot nach Beutebucht gesteckt. Einer dieser Riesen, Gorlash, hat meine Kapitänstruhe gestohlen. Er sagte, er wolle sie als Schnupftabakdose. Diese Dreistigkeit!\n\nIch habe gehört, dass Gorlash an der Küste östlich von hier sein Unwesen treibt. Findet ihn und bringt mir meine Truhe zurück! Tut das, und Ihr habt Euch die Dankbarkeit eines Kapitäns verdient!", sourceObjective = "Bringt Smotts' Truhe zu Hecklebury Smotts nach Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8552] = { id = 8552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schärpe mit Monogramm", description = "Auf dem Saum dieser feinen Schärpe sind die Buchstaben \"HS\" eingestickt.", sourceObjective = "Bringt die Schärpe mit Monogramm zu ihrem Besitzer zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8553] = { id = 8553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Entersäbel des Kapitäns", description = "Nachdem ich mein Schiff an diese Riesen verlor, kaufte ich mir ein neues. Ich hab es SMOTTS' REVENGE genannt, Vorräte gekauft, eine Crew angeheuert und Segel gesetzt, um diese Schurken ausfindig zu machen. Ich habe sie auch gefunden, aber... sie haben mich besiegt. Sie haben die SMOTTS' REVENGE zerschmettert, meine zweite Crew umgebracht und mich in einem weiteren Rettungsboot ausgesetzt.\n\nDieses Mal hat ein anderer Riese, Negolash, meinen Entersäbel gestohlen.\n\nStellt Euch Negolash und bringt mir meinen Entersäbel!\n\nSprecht mit Knirpsens. Er war mein Smutje auf der SMOTTS' REVENGE und hat den letzten Angriff überlebt. Er kann Euch helfen, den Riesen zu finden.", sourceObjective = "Sprecht mit Knirpsens.", sourceObjectiveStatus = "unverified-source-field" }
quests[8554] = { id = 8554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Negolash entgegentreten", description = "Negolash ist ein hungriger Riese.\n\nAls die Riesen unser Schiff zerstörten, ging Negolash schnurstracks in meine Kombüse. Er hatte keinen Appetit auf die Crew wie die anderen Riesen. Negolash wollte Wein... und meine gegrillten Bussardflügel. Die sind meine Spezialität. Für das Rezept musste ich bis ins Ödland reisen!\n\nWenn Ihr den Riesen anlocken wollt, dann besorgt Euch etwas Wein und einen Haufen Bussardflügel. Legt sie in unser altes Rettungsboot, an der Küste südöstlich von hier. Sobald Negolash das Essen riecht, wird er bestimmt kommen!", sourceObjective = "Bringt 10 gegrillte Bussardflügel und 5 Flaschen Dschungelrankenwein zu Käpt'n Smotts Rettungsboot.\n\nTötet Negolash und bringt Smotts' Entersäbel zu Kapitän Smotts ins Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[8555] = { id = 8555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bund der Drachenschwärme" }
quests[8556] = { id = 8556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegel der unnachgiebigen Stärke", description = "Man sagt, dass die Ringe, die von den Leutnants der Qiraji getragen werden, ungeheure Fähigkeiten verleihen. Die verderbten Edelsteine, mit denen sie verziert sind, könnten theoretisch mit reinerem Material ausgetauscht werden, um unbefleckte Versionen der Ringe herzustellen.\n\nDie Edelsteine, die die Götzen der Qiraji schmücken, würden sich dafür gut eignen, da sie von besserer Qualität sind.\n\nBringt mir den Ring und Götzen und ich werde einen mächtigen Ring für Euch anfertigen, {class}.", sourceObjective = "Bringt 1 Gebieterring der Qiraji, 2 züngelnde Götzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir den Ring und die Gegenstände besorgt, {name}?", completion = "Ich werde den Edelstein auf dem Ring für Euch austauschen. Ihr werdet sehen, dass der Effekt viel... angenehmer ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8557] = { id = 8557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tuch der unnachgiebigen Stärke", description = "Ich freue mich, dass Ihr uns bei unserem Angriff auf Ahn'Qiraj unterstützen wollt, {name}. Ich kann einen schützenden Gegenstand für Euch herstellen, der Euch im Kampf gegen unseren Feind behilflich sein wird, {class}.\n\nIch benötige dafür ein Tuch der Qiraji, das ich dann natürlich für Euch anpassen werde. Außerdem bräuchte ich noch Götzen und Skarabäen, die ich zu einer passenden Schnalle verarbeiten möchte.\n\nIhr werdet bestimmt nicht enttäuscht sein.", sourceObjective = "Bringt 1 Kampftuch der Qiraji, 2 Onyxgötzen, 5 Sillberskarabäen und 5 Knochenskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die Materialien für den Umhang gebracht, {name}?", completion = "Ah ja... dieses Tuch ist perfekt.\n\nNehmt diesen Umhang, {name}. Möge er Euch vor der üblen Magie der Qiraji schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8558] = { id = 8558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sichel der unnachgiebigen Stärke", description = "Die Qiraji und ihre Diener besitzen Gegenstände, die aus dem seltensten und feinsten Material hergestellt werden: Knochen von riesengroßen uralten Kreaturen, Edelsteine aus den Tiefen der Erde, reines und starkes Metall.\n\nAllein der Anblick dieser Qirajiartefakte erfüllt mich mit dem Drang, mein Handwerk an ihren zerschmetterten und geschmolzenen Stücken auszuüben. Beweist dem Zirkel Eure Loyalität, {name}, und ich werde aus den feinsten Qirajibestandteilen eine mächtige Waffe für Euch herstellen.", sourceObjective = "Bringt 1 Stachelgriff der Qiraji, 2 Alabastergötzen, 5 Kristallskarabäen und 5 Steinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, {name}?", completion = "Das habt Ihr gut gemacht, {class}. Dies ist ein Meisterstück... die Balance ist perfekt.\n\nNehmt Eure Waffe, {name}. Schwingt sie zuversichtlich und vernichtet unsere Feinde!", sourceObjectiveStatus = "unverified-source-field" }
quests[8559] = { id = 8559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schienbeinschützer des Eroberers", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Befehlsbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", sourceObjective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Krieges, 5 Elfenbeinskarabäen und 5 Goldskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8560] = { id = 8560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinschützer des Eroberers", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", sourceObjective = "Bringt Ouros intakte Haut, 2 Götzen des Todes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ja... die Haut des Wurms wird eine wunderbar schützende Schicht abgeben. In Verbindung mit den stärksten Teilen der Qiraji, die wir auf unserem Weg hierher zerstört haben, sollte dies eine prächtige Rüstung abgeben. Möge sie Euch bei der Begegnung des unaussprechlichen Grauens helfen, das Euch im Innern erwarten wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[8561] = { id = 8561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krone des Eroberers", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, {name}. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", sourceObjective = "Bringt Vek'nilashs Reif, 2 Götzen der Sonne, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8562] = { id = 8562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte des Eroberers", description = "Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", sourceObjective = "Bringt den Knochenpanzer des Alten Gottes, 2 Götzen des Krieges, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Brustplatte als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", sourceObjectiveStatus = "unverified-source-field" }
quests[8563] = { id = 8563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Hexenmeister", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Der Lehrer für junge Hexenmeister hier auf der Insel der Sonnenwanderer ist Beschwörer Teli'Larien. Sprecht mit Beschwörer Teli'Larien, um herauszufinden, welche Ausbildung er Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nBeschwörer Teli'Larien - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", sourceObjective = "Sprecht mit Beschwörer Teli'Larien - dem Hexenmeisterlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[8564] = { id = 8564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbildung zum Priester", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Die Lehrerin für junge Priester hier auf der Insel der Sonnenwanderer ist Matrone Arena. Sprecht mit Matrone Arena, um herauszufinden, welche Ausbildung sie Euch anbieten kann. Die Ausbildung hat ihren Preis, bringt also ein paar Münzen mit Euch.\n\nMatrone Arena - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms, auf der unteren Ebene, anzutreffen.", sourceObjective = "Sprecht mit Matrone Arena - der Priesterlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", sourceObjectiveStatus = "unverified-source-field" }
quests[8565] = { id = 8565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergangene Siege im Arathibecken" }
