quests[8572] = { id = 8572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Veteranen", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, {name}.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", sourceObjective = "Bringt 7 cenarische Gefechtsabzeichen, 4 cenarische Versorgungsabzeichen und 4 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8573] = { id = 8573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Feldherrn", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Burg Cenarius erhalten habt, dienen zu weit mehr als der Angeberei, {name}.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", sourceObjective = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 20 cenarische Strategieabzeichen und 1 Mal des Cenarius zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8574] = { id = 8574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlachtrüstung des Gefolgsmanns", description = "Die Abzeichen, die Ihr für Eure Erfüllung von Kampf-, Logistik- und taktischen Aufträgen für Windruferin Prachthorn erhalten habt, dienen zu weit mehr als der Angeberei, {name}.\n\nIhr solltet deren Wert besser zu schätzen wissen. Da Ihr gegenüber unserer Organisation Loyalität bewiesen habt, kann ich Euch bestimmte Ausrüstungsgegenstände anbieten, die wir lediglich für unsere engsten Verbündeten im Austausch gegen diese Abzeichen bereithalten.", sourceObjective = "Bringt 15 cenarische Gefechtsabzeichen, 20 cenarische Versorgungsabzeichen, 17 cenarische Strategieabzeichen und 1 Mal von Remulos zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius.", sourceObjectiveStatus = "unverified-source-field" }
quests[8575] = { id = 8575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azuregos' magisches Buch", description = "Ihr könnt kein einziges Wort in diesem Buch verstehen. Ihr wisst nicht einmal in welcher Sprache es geschrieben wurde!", sourceObjective = "Bringt Azuregos' magisches Buch zu Narain Pfauentraum in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[8576] = { id = 8576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung des Buchs" }
quests[8577] = { id = 8577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stewvul, ehemals allerbester Freund", description = "Tja, um irgendetwas übersetzen zu können, brauche ich meine Wahrsagerbrille. Unglücklicherweise wurde sie vor einiger Zeit von meinem Ex-'Besten Freund für immer', Stewvul gestohlen. Er hat mir mein Herz fünffach gebrochen und mich dann hier verrotten lassen.\n\nMithilfe meiner Kristallkugel konnte ich seinen momentanen Aufenthaltsort einigermaßen genau bestimmen. Er ist entweder am Graumähnenwall im Silberwald oder in irgend so einer Portaldimension in der Scherbenwelt, die 'grad von der brennenden Legion überrannt wird. Schätze, es liegt jetzt an Euch, ihn ausfindig zu machen und mir meine Brille zurückzubringen, {name}!", sourceObjective = "Narain Pfauentraum möchte, dass Ihr seinen Ex-'Besten Freund für immer' (B.F.F.I.) Stewvul ausfindig macht. Nehmt ihm die gestohlene Wahrsagerbrille ab und bringt sie Narain zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8578] = { id = 8578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrsagerbrille? Kein Problem!", description = "<Ihr hört einen erleichterten Seufzer aus der Kiste.>\n\nIhr wollt nur seine Wahrsagerbrille? Großartig! Kein Problem, gebt mir kurz 'ne Minute, um… Hey! Wo zur verdammten…!\n\nEs gibt eine schlechte und eine verdammt schlechte Nachricht. Die Schlechte ist, dass ich die Brille verloren habe. Die viel schlimmere Nachricht ist, ich habe sie letzten Monat beim Herumstreifen im Geschmolzenen Kern irgendwo liegen lassen. Jep, der Geschmolzene Kern... Tja, so etwas passiert. Tschüss!", sourceObjective = "Findet Narains Wahrsagerbrille und bringt sie Narain Pfauentraum in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[8579] = { id = 8579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sterbliche Helden", progress = "Wir spüren die Anwesenheit unserer versklavten Brüder tief im Innern von Ahn'Qiraj; dennoch wäre selbst eine Armee von Drachen nicht genug, um sie zu befreien, {race}.\n\nDer gleiche Zauber, der sie gefangen hält, würde uns der Gewalt C'Thuns unterwerfen, sobald wir ihm näher kämen.\n\nDer Alte Gott hat unser Kommen vorhergesehen. All unsere Hoffnung ist dahin. Was könnte ein bloßer Sterblicher wie Ihr daran wohl ändern?", completion = "Ihr werdet den Qiraji innerhalb der Behausung des Alten Gottes entgegentreten? Ist das eine Art von Galgenhumor, dessen ich mir nicht bewusst bin?\n\nIch kann sehen, dass Ihr es ernst meint, {name}. Also bitte. Eure Chancen, auch wenn sie noch so gering sein mögen, sind momentan dennoch größer als unsere.\n\nGenau wie Nozdormu und Hirschhaupt die Qiraji vor tausend Jahren dank des Bündnisses zwischen den Sterblichen und der Drachen besiegt haben, so sollen auch wir uns zusammenschließen. Gewinnt das Vertrauen des bronzenen Drachenschwarms und somit das unsere. Nur so können wir einen wahren Helden aus Euch machen." }
quests[8580] = { id = 8580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Feuerblüten!", description = "Hey, {class}! Ja, Ihr da! Es gibt da massenhaft Feuerblüten, die von der Horde für die Vorbereitungen des Krieges von Ahn'Qiraj benötigt werden. Vielleicht werden sie ja in so nette Dinge verarbeitet, die dann in die Luft gehen? Vielleicht geben sie sie der Allianz aber auch als Treibstoff für ihre Dampfpanzer? Wer weiß? Nicht Pele'keiki!\n\nPele'keiki weiß nur eines... er weiß, dass Ihr ihm helfen und einen Haufen Feuerblüten für ihn sammeln werdet! Oder?", sourceObjective = "Bringt 20 Feuerblüten zu Fledermausreiter Pele'keiki im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8581] = { id = 8581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Feuerblüten!" }
quests[8582] = { id = 8582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht lila Lotus!", description = "Lila Lotus, {class}, ist eine Zutat für nicht wenige Tränke, Elixiere und Öle, von denen uns einige im Krieg von Ahn'Qiraj von Nutzen sein werden. Wir werden eine stattliche Menge dieser Tränke für die Kriegsanstrengungen herstellen müssen. Ich werde zusätzlich noch experimentieren, um weitere Verwendungsmöglichkeiten für Lila Lotus zu finden. Allerdings werde ich dafür eine große Anzahl dieser Pflanzen benötigen.\n\nJetzt zu Eurer Aufgabe. Zieht durch die Felder und sammelt so viel Lila Lotus ein, wie Ihr könnt. Wärt Ihr dazu in der Lage?", sourceObjective = "Bringt 20 lila Lotus zu Apothekerin Jezel im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8583] = { id = 8583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr lila Lotus!" }
quests[8584] = { id = 8584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragt mich nie nach meinen Angelegenheiten", description = "Wenn es eine Sache gibt, die Ihr von mir wissen solltet, dann ist es das: Fragt mich NIEMALS nach meinen Angelegenheiten! Ich arbeite mit Dingen, die Ihr einfach nicht verstehen könnt. Zum Beispiel: Wisst Ihr was ein psychotronischer Muzzledorf ist? Natürlich nicht! Genau deshalb überlassen wir das Planen auch mir und das Beschaffen Euch.\n\nWie ich schon sagte, wenn es funktionieren soll, dann brauchen wir ein 500 Pfund-Hühnchen.\n\nGeht nach Gadgetzan und sprecht mit Dirge Schnetzelhack - er kann Euch bei der Suche nach dem passenden Exemplar auf die Sprünge helfen.", sourceObjective = "Narain Pfauentraum in Tanaris möchte, dass Ihr mit Dirge Schnetzelhack in Gadgetzan sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[8585] = { id = 8585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Insel des Schreckens!", description = "Der Legende nach haben die Chimaerok von der Insel des Schreckens in Feralas das saftigste und zarteste Fleisch weit und breit! Nun kommt es, dass diese Chimaerok ein Familienoberhaupt haben, das, nach entsprechender Zubereitung, wie ein 500 Pfund-Hühnchen aussehen könnte... oder auch nicht.\n\nGeht zu der Insel des Schreckens, tötet Lord Lakmaeran und bringt mir seinen frischen Kadaver. Das sollte den Gnom zufrieden stellen. Um mich zufrieden zu stellen, müsst Ihr ein paar Chimaeroklenden in Eure Finger bekommen.\n\nSollte Euch das gelingen, bekommt Ihr Euer 500 Pfund-Hühnchen und ein kleines Extra.", sourceObjective = "Dirge Schnetzelhack in Tanaris möchte, dass Ihr Lakmaerans Kadaver sowie 20 Chimaeroklenden beschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[8586] = { id = 8586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirges abgefahrene Chimaerokkoteletts", description = "Mein Rezept is fertig! Was ich jetzt von Euch brauche ist Raketentreibstoff und Tiefsteinsalz. Ich kümmere mich um die Gewürze und das Fleisch, das Ihr mir gebracht habt, sorgt für den Rest.\n\nSobald Ihr mir die benötigten Zutaten gebracht habt, könnt Ihr das fertige Hühnchen zu Narain bringen.", sourceObjective = "Dirge Schnetzelhack in Gadgetzan möchte, dass Ihr ihm 20 Einheiten Goblinraketentreibstoff und 20 Einheiten Tiefsteinsalz bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8587] = { id = 8587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Narain", description = "Ich bin ein Goblin, der sein Wort hält, Kind. Hier ist Euer 500 Pfund-Hühnchen.\n\nWas ein Gnom mit einem 500 Pfund-Hühnchen möchte, werde ich wohl nie verstehen...\n\n<Dirge grummelt etwas Unverständliches.>\n\nWahrscheinlich um darin zu schlafen... schmutzige Gnome...", sourceObjective = "Bringt das 500 Pfund-Hühnchen zu Narain Pfauentraum in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[8588] = { id = 8588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht schweres Leder!", description = "Da wir uns gerade auf den bevorstehenden Krieg vorbereiten, wäre es wahrscheinlich das Beste, wenn wir alle benötigten Güter zuerst beschaffen, meint Ihr nicht? Einer der benötigten Vorräte besteht aus schwerem Leder. Wir verwenden es für fast alles, von Verstärkungen bis hin zu Rüstungen und guten alten Planen.\n\nAllerdings brauchen wir erst einmal mehr davon. Das ist Eure Aufgabe, {class}. Wetzt Euer Messer und bringt mir ein Bündel schweres Leder. Alles weitere besprechen wir dann.", sourceObjective = "Bringt 10 Einheiten schweres Leder zu Kürschner Jamani im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8589] = { id = 8589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr schweres Leder!" }
quests[8590] = { id = 8590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht dickes Leder!", description = "Ich bin froh, dass Ihr darüber mit mir sprechen möchtet, {class}. Es sieht ganz so aus, als ob die Vorbereitungen der Horde für den Krieg in Ahn'Qiraj in vollem Gange sind. Ihr und ich müssen aber noch unseren Teil leisten.\n\nIch wurde mit der Sammlung einer großen Menge dicken Leders beauftragt, das für die Herstellung von allerlei Kriegsmaterialien benötigt wird. Ich brauche Euch, um für mich loszuziehen und mir welches zu besorgen. Ihr würdet Euch Ehre und das Wohlwollen der Horde verdienen können. Würdet Ihr uns also helfen?", sourceObjective = "Bringt 10 Einheiten dickes Leder zu Unteroffizierin Umala im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8591] = { id = 8591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr dickes Leder!" }
quests[8592] = { id = 8592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiara des Orakels", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, {name}. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", sourceObjective = "Bringt Vek'nilashs Reif, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8593] = { id = 8593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinkleider des Orakels", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", sourceObjective = "Bringt Ouros intakte Haut, 2 Götzen des Lebens, 5 Goldskarabäen und 5 Tonskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ja... die Haut des Wurms wird eine wunderbar schützende Schicht abgeben. In Verbindung mit den stärksten Teilen der Qiraji, die wir auf unserem Weg hierher zerstört haben, sollte dies eine prächtige Rüstung abgeben. Möge sie Euch bei der Begegnung des unaussprechlichen Grauens helfen, das Euch im Innern erwarten wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[8594] = { id = 8594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantel des Orakels", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", sourceObjective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Wiedergeburt, 5 Silberskarabäen und 5 Elfenbeinskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8595] = { id = 8595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sterbliche Helden", progress = "Einen Qirajilord zu töten ist eine bemerkenswerte Tat für einen Sterblichen, {name}. Allerdings sind sie zahlreich und mächtig. Bezwingt sie auch weiterhin und erweist Euch als unser Held.", completion = "Ihr dient uns auch weiterhin tapfer, {name}. Unser Bündnis bleibt bestehen." }
quests[8596] = { id = 8596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fußlappen des Orakels", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Befehlsbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", sourceObjective = "Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Todes, 5 Bronzeskarabäen und 5 Goldskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8597] = { id = 8597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachisch für Dummies", description = "Ich wusste, dass dieses Buch eines Tages nützlich sein würde! Glücklicherweise war ich clever und vorausschauend genug und habe es an einem sicheren Ort verstaut.\n\nKeine Angst, es befindet sich an einem Platz, auf den niemand kommen würde! Ich brauchte einen Gyrokopter, um das erste Mal dorthin zu gelangen. Bedauerlicherweise musste ich auf meinem Rückweg am Strand bruchlanden. Ich verdanke es diesem Unfall, dass ich diese gnomischen Superpsychokräfte erlangt habe!\n\nHaltet nach meinem verunglückten Gyrokopter irgendwo am Landendestrand Ausschau und schwimmt von da aus in Richtung Süden! Ihr werdet die Stelle erkennen, wenn Ihr sie seht!", sourceObjective = "Findet Narain Pfauentraums Buch, das auf einer Insel der Südlichen Meere vergraben ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8598] = { id = 8598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "lÖsEGeLd", description = "<Der Text der Nachricht wurde aus unterschiedlichen, ausgeschnittenen Buchstaben zusammengesetzt und auf das Papier geklebt.>\n\nWir haben dein kostbares Buch, Gnom. Wenn du es jemals wiedersehen willst, dann machst du genau das, was wir dir sagen.\n\n<Dem Ganzen folgt eine ausführliche Liste von Anweisungen, die sich über 3 Seiten zieht.>\n\nBringt das Geld und kommt alleine!", sourceObjective = "Bringt die Lösegeldforderung zu Narain Pfauentraum in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[8599] = { id = 8599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebesbrief für Narain", description = "Es kommt nicht häufig vor, dass ich Besuch bekomme. Genaugenommen hatte ich das letzte Mal einen Besucher, als ich diesen liebreizenden, süßen Gnom nach dem Absturz mit seiner Flugmaschine gerettet habe.\n\n<Meridith starrt gedankenverloren ins Nichts.>\n\nKennt Ihr ihn? Narain? Narain Pfauentraum? Oh, es würde mir so viel bedeuten, wenn ihm jemand eine Nachricht von mir überbringen würde. Ich muss ihm mitteilen, was ich empfinde! Ich weiß, dass es Liebe ist! Ich weiß es einfach!\n\nKönntet Ihr Narain vielleicht eine Nachricht zustellen? Ich wäre Euch für immer zu Dank verpflichtet!", sourceObjective = "Bringt Meridiths Liebesbrief zu Narain Pfauentraum in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[8600] = { id = 8600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht unverwüstliches Leder!", description = "Ich glaube, dass die richtige Handhabung eines Messers wichtiger ist als dessen Schneide. Beherrscht man sein Handwerk, kann man auch mit der stumpfsten Klinge schneiden, oder, {class}? Ihr und ich, wir haben solche Probleme aber nicht, da wir im Besitz der schärfsten Klingen sind.\n\nNaja, egal. Ich habe eine Aufgabe für Euch. Im Auftrag der Horde und im Namen der Kriegsvorbereitungen von Ahn'Qiraj, möchte ich Euch bitten, mir eine gewisse Anzahl unverwüstliches Leder zu besorgen. Wäre das möglich?", sourceObjective = "Bringt 10 Einheiten unverwüstliches Leder zu Doktor Serratus im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8601] = { id = 8601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr unverwüstliches Leder!" }
quests[8602] = { id = 8602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulterstücke des Sturmrufers", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", sourceObjective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Lebens, 5 Goldskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8603] = { id = 8603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Orakels", description = "Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", sourceObjective = "Bringt die Hülle des Alten Gottes, 2 Götzen des Todes, 5 Steinskarabäen und 5 Kristallskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Gewänder als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", sourceObjectiveStatus = "unverified-source-field" }
quests[8604] = { id = 8604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Wollverbände!", description = "Seid gegrüßt, {class}. Während der Vorbereitungen für den Krieg in Ahn'Qiraj, bin ich hier, um die Bemühungen der Horde beim Zusammentragen von Wollverbänden zu koordinieren. Auf dem Schlachtfeld können sich unsere Soldaten nicht auf die Gegenwart eines Heilers verlassen, der sie am Leben hält. Glaubt mir, ich weiß das. Daher stellen wir all diese Sanitätskästen für sie zusammen.\n\nSolltet Ihr Zeit haben: Ich brauche sehr viele Wollverbände. Bringt sie hierher zu mir und ich werde sehen, dass Ihr dafür ordnungsgemäß entlohnt werdet.", sourceObjective = "Bringt 20 Wollverbände zu Heiler Fernläufer im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8605] = { id = 8605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Wollverbände!" }
quests[8606] = { id = 8606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lockvogel!", description = "Ich hab's! Wir werden Folgendes tun. Ich werde einen Sack mit Steinen füllen und Ihr werdet ihn überbringen. Ich weiß, dass man die Übergabe von mir verlangt und das werde ich auf gewisse Weise auch tun.\n\n<Narain sieht Euch von oben bis unten an.>\n\nJa, das dürfte passen. Nehmt diesen Turban, diese Robe und den Sack voller Steine, geht dann zu dem Übergabepunkt in Winterquell.\n\nAlles, was Ihr benötigen werdet, befindet sich in diesem Spezialset. Sobald sie auftauchen, um die Ware abzuholen, macht Ihr sie fertig! Das wird ihnen lehren, was es heißt, sich mit Narain anzulegen!", sourceObjective = "Narain Pfauentraum in Tanaris möchte, dass Ihr nach Winterquell reist und die Tasche voller Gold, so wie es die Buchnapper angegeben haben, am Übergabepunkt platziert.", sourceObjectiveStatus = "unverified-source-field" }
quests[8607] = { id = 8607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Magiestoffverbände!", description = "Ich nehme doch hoffentlich richtig an, dass Ihr mit mir sprecht, weil Ihr mich bei dem Sammelauftrag unterstützen wollt, der mir anvertraut wurde? Gut! Mir ist es egal wie, aber ich wünsche mir wirklich, dass Ihr einige Magiestoffverbände für mich zusammentragt. Ganz frisch hergestellte wären wunderbar, aber nicht unbedingt zwingend. Bringt sie hierher zu mir, {class}, dann werde ich sehen, dass Ihr ordnungsgemäß dafür entlohnt werdet.", sourceObjective = "Bringt 20 Magiestoffverbände zu Lady Kahler im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8608] = { id = 8608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Magiestoffverbände!" }
quests[8609] = { id = 8609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Runenstoffverbände!", description = "Für viele scheint es unausweichlich, dass die Streitkräfte von Horde und Allianz bei Ahn'Qiraj aufeinander treffen werden. Interessanterweise handelt es sich dabei nicht um einen Krieg gegeneinander, sondern vielmehr gegen die Silithiden oder was auch immer sie kontrolliert. Beide Seiten leisten ihren Teil, um die nötigen Ressourcen für eine erfolgreiche Kriegsführung aufzubringen.\n\nIch sammle Runenstoffverbände, die an die Soldaten ausgeteilt werden. Ich bräuchte dabei allerdings Unterstützung. Könntet Ihr mir dabei helfen, {class}?", sourceObjective = "Bringt 20 Runenstoffverbände zu Steingardist Lehmhuf im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8610] = { id = 8610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Runenstoffverbände!" }
quests[8611] = { id = 8611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht magere Wolfsteaks!", description = "Ich stehe hier nicht nur herum, um etwas Farbe abzubekommen, {class}. Es gilt Kriegsvorbereitungen zu treffen. Wenn wir diese Viecher in Ahn'Qiraj niederschmettern möchten, dann müssen wir bereit sein, und dazu gehört auch Proviant!\n\nIch sammle und salze hier magere Wolfsteaks für den anstehenden Krieg ein. Da ich hier bleiben muss, um mich um alles zu kümmern, bräuchte ich Eure Hilfe. Zieht aus, um Wölfe zu töten, bereitet ihr Fleisch zu mageren Wolfsteaks zu und bringt diese dann zu mir. Alles klar?", sourceObjective = "Bringt 20 magere Wolfsteaks zu Blutwache Rawtar im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8612] = { id = 8612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr magere Wolfsteaks!" }
quests[8613] = { id = 8613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht Tüpfelgelbschwänze!", description = "Wär' heute nicht ein guter Tag zum Angeln? Praktisch, denn es sieht aus, als würde ich hier noch 'ne Menge Fisch brauchen. Die Horde hat mich mit der Sammlung von einem Haufen Tüpfelgelbschwänzen beauftragt. Sie sagen, dass sie sie für ihre Vorbereitungen für den Krieg in Ahn'Qiraj benötigen. Ich hab' gesagt, dass ich mein Bestes geben werde. Ich brauche also etwas Unterstützung. Ihr werdet mir doch helfen, {class}, oder?", sourceObjective = "Bringt 20 Tüpfelgelbschwänze zu Angler Lin'do im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8614] = { id = 8614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr Tüpfelgelbschwänze!" }
quests[8615] = { id = 8615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht gebackenen Lachs!", description = "Die Vorbereitungen für den Krieg von Ahn'Qiraj sind ein immenses Unterfangen, {class}. All die Materialien, die hier gesammelt werden, sind gleichermaßen wichtig - ob es Metall für Waffen oder Proviant zum Essen ist. Hat man seit Tagen nichts gegessen, so kann man, wenn es darauf ankommt, auch nicht mehr seine Axt schwingen.\n\nDafür sammeln wir hier so viele Nahrungsmittel wie wir können. Ich sammle zum Beispiel gebackenen Lachs, ein Gericht, das wegen seiner Nahrhaftigkeit und guten Lagerbedingungen gewählt wurde. Könnt Ihr mir bei dieser Aufgabe helfen, {class}?", sourceObjective = "Bringt 20 Stück gebackenen Lachs zu Häuptling Scharfklaue im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8616] = { id = 8616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr gebackenen Lachs!" }
quests[8617] = { id = 8617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht sengende Kernsteine!", description = "Es ist an der Zeit, dass Ihr etwas zu den Kriegsanstrengungen von Ahn'Qiraj beitragt, {class}. Die ruhigen Tage, an denen Ihr Eure Zeit mit Vergnügen verbracht habt, sind vorbei. Jetzt sollt Ihr mir und der Horde dienen... und ich versichere Euch, dass ich nicht so nachsichtig wie der Kriegshäuptling bin.\n\nSammelt Eure Kräfte, Eure Gilde, wenn möglich, und dringt in den Geschmolzenen Kern vor. Ihr werdet feststellen, dass man dort an etlichen Stellen sengende Kernsteine finden kann. Bringt mir davon eine auseichend große Menge.", sourceObjective = "Bringt 50 sengende Kernsteine zu General Zog in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8618] = { id = 8618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Horde braucht mehr sengende Kernsteine!" }
quests[8619] = { id = 8619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Schwermut", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8620] = { id = 8620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der einzige Weg", description = "Ich hätte es wissen müssen. Mein Erzfeind, Doktor Weavil, hat wieder seine dreckigen Finger im Spiel! Jetzt, nach Eurem Versagen in Winterquell, hat Doktor Weavil mein Buch zerstört! Wie wollt Ihr jetzt die Welt retten, Held?\n\nDie Nachricht die ich erhalten habe, gab an, dass die einzig bekannte Kopie von \"Drachisch für Dummies: Band 2\" in 8 Teile zerrissen und im Wind zerstreut wurde! Solltet Ihr diese fehlenden Kapitel irgendwie finden können, dann verwendet diesen magischen Bucheinband, um sie wieder zusammen zu flicken. Kehrt dann zu mir zurück.", sourceObjective = "Findet die 8 verlorenen Kapitel von Drachisch für Dummies und vereint sie mit dem magischen Bucheinband. Bringt das vollständige Buch Drachisch für Dummies: Band 2 zu Narain Pfauentraum in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[8621] = { id = 8621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fußschützer des Sturmrufers", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Dominanzbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", sourceObjective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen der Weisen, 5 Bronzeskarabäen und 5 Tonskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8622] = { id = 8622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halsberge des Sturmrufers", description = "Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", sourceObjective = "Bringt den Knochenpanzer des Alten Gottes, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Brustplatte als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", sourceObjectiveStatus = "unverified-source-field" }
quests[8623] = { id = 8623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diadem des Sturmrufers", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, {name}. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", sourceObjective = "Bringt Vek'lors Diadem, 2 Götzen der Wiedergeburt, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8624] = { id = 8624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamaschen des Sturmrufers", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", sourceObjective = "Bringt die Haut des großen Sandwurms, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ja... die Haut des Wurms wird eine wunderbar schützende Schicht abgeben. In Verbindung mit den stärksten Teilen der Qiraji, die wir auf unserem Weg hierher zerstört haben, sollte dies eine prächtige Rüstung abgeben. Möge sie Euch bei der Begegnung des unaussprechlichen Grauens helfen, das Euch im Innern erwarten wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[8625] = { id = 8625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulterpolster des Mysteriums", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", sourceObjective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Todes, 5 Steinskarabäen und 5 Bronzeskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8626] = { id = 8626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fußschützer des Hetzers", description = "Qirajimagie ist sehr stark und uralt. Die mächtigsten Qiraji handhaben Gegenstände, die so machtvoll sind, dass sie sogar einem Drachen Einhalt gebieten.\n\nBringt mir die Befehlsbindungen der Qiraji sowie andere geringfügigere Bestandteile und ich werde ein Paar mächtige Stiefel für Euch herstellen.\n\nIhr werdet sie im Kampf gegen den Feind als nützlich empfinden.", sourceObjective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Lebens, 5 Steinskarabäen und 5 Knochenskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Gegenstände erlangt, {name}?", completion = "Das habt Ihr gut gemacht, {name}. Ihr habt bewiesen, dass Ihr kein gewöhnlicher Sterblicher seid.\n\nIch gebe Euch dies hier mit Zuversicht, auf dass sie Euch beim Niederschmettern der bösartigen Qiraji behilflich sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8627] = { id = 8627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte des Rächers", description = "Der unaussprechliche Alte Gott erwacht langsam aus seinem Schlummer unterhalb Ahn'Qirajs. Das schreckliche Schicksal, das Azeroth erwartet, könnte in Tagen oder auch Jahren Wirklichkeit werden, Zeit spielt für Wesen seiner Macht keine Rolle.\n\nStehen die Sterne günstig, wird er furchtbaren Zorn gegen alle Lebewesen walten lassen. Ihr müsst dem zuvorkommen und einen Weg finden, um seiner Existenz ein Ende zu bereiten.\n\nTut dies und bringt mir ein Stück seiner Hülle. Ich werde Euch eine Rüstung gewähren, die noch kein Sterblicher getragen hat... Rüstung für einen Helden, der einen Gott bezwungen hat!", sourceObjective = "Bringt den Knochenpanzer des Alten Gottes, 2 Götzen der Weisen, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus.", progress = "Der furchtbare C'Thun wartet ruhend in seiner Behausung in Ahn'Qiraj.", completion = "Ich habe nicht erwartet, dass Ihr von Eurer Unternehmung zurückkehrt, {name}.\n\nIhr habt eine größere Vorsehung erfüllt als die der meisten sterblichen Wesen.\n\nIndem Ihr C'Thun bezwungen habt, habt Ihr nicht nur ganz Azeroth gerettet, sondern auch kosmische Ereignisse in Gang gesetzt, die weit über Eurem Vorstellungsvermögen liegen.\n\nNehmt diese Brustplatte als Zeichen des Ruhms und der Bürde an, die Euch in Folge Eurer Taten erwarten werden.\n\nMöge ihre Macht bei Euren zukünftigen Herausforderungen mit Euch sein, Göttertöter!", sourceObjectiveStatus = "unverified-source-field" }
quests[8628] = { id = 8628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krone des Rächers", description = "Die Zwillingsimperatoren... ihr unaufhörliches Flüstern martert langsam meinen Verstand. Sie verhöhnen mich, wissend, dass ich nicht tiefer in ihr Reich vordringen kann, um meinen Bruder Arygos zu retten.\n\nIn meinen Visionen sehe ich ihre monströsen Fratzen, die mit mächtigen Kronen geschmückt sind. Ich werde meine Vergeltung noch bekommen... ich werde diese Symbole der Qirajimacht in solche verwandeln, die unserem Nutzen gerecht werden.\n\nBringt mir die benötigten Bestandteile, {name}. Ich werde Euch dafür ein Kopfstück von unvergleichlicher Macht geben.", sourceObjective = "Bringt Vek'lors Diadem, 2 Götzen der Wiedergeburt, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ihr seid erfolgreich gewesen! Das Flüstern der Zwillingsimperatoren ist verstummt.\n\nNehmt dies als Belohnung. Der bloße Anblick hiervon wird Furcht in die Herzen der Qiraji treiben... es soll sie an ihre gefallenen Anführer erinnern und an den Sterblichen, der sie niederstreckte.", sourceObjectiveStatus = "unverified-source-field" }
quests[8629] = { id = 8629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinschützer des Rächers", description = "Ihr möchtet Euch also uns gegenüber bewähren, Sterblicher? Nun gut, vielleicht können wir uns ja gegenseitig helfen.\n\nDer uralte Sandwurm, Ouro, ist ein Geschöpf von legendärer Macht. Man sagt, dass er von dem Alten Gott selbst als Gespött des Lebens erschaffen wurde.\n\nSeine Haut ist unnatürlich... dick, fast unbezwingbar und dennoch flexibel, was ihm ermöglicht, sich mit der Geschwindigkeit und Grazie eines kleineren Lebewesens zu bewegen.\n\nBringt mir eine Probe seiner Haut sowie andere geringfügigere Bestandteile und ich werde mächtige Gamaschen für Euch herstellen.", sourceObjective = "Bringt die Haut des großen Sandwurms, 2 Götzen des Kampfes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile beschafft, {name}?", completion = "Ja... die Haut des Wurms wird eine wunderbar schützende Schicht abgeben. In Verbindung mit den stärksten Teilen der Qiraji, die wir auf unserem Weg hierher zerstört haben, sollte dies eine prächtige Rüstung abgeben. Möge sie Euch bei der Begegnung des unaussprechlichen Grauens helfen, das Euch im Innern erwarten wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[8630] = { id = 8630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulterstücke des Rächers", description = "Man sagt unter uns, dass die kunstvoll verzierten Schulterpanzerungen, die von den sterblichen Völkern getragen werden, zu Beginn eine Nachahmung von Drachenflügeln werden sollten.\n\nBringt mir die Bindungen, die von den höchsten Anführern der Qiraji getragen werden und ich werde sie in ein Paar Schulterstücke verarbeiten, die furchteinflößender als die Flügel Nefarians selbst sind!", sourceObjective = "Bringt die Dominanzbindungen der Qiraji, 2 Götzen des Lebens, 5 Kristallskarabäen und 5 Goldskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus.", progress = "Habt Ihr die von mir benötigten Bestandteile gesammelt?", completion = "Ich werde diese Schulterstücke aus dem Material, das Ihr mir gebracht habt, und den Schuppen der gefallenen Qirajifeinde herstellen, Sterblicher. Mögen sie Euch den Schutz geben, den Ihr braucht, und möge ihr Anblick unseren Feinden Furcht einflößen.", sourceObjectiveStatus = "unverified-source-field" }
